  min_age = excluded.min_age,
  max_age = excluded.max_age,
  requires_itr = excluded.requires_itr,
  requires_existing_relationship = excluded.requires_existing_relationship,
  reward_rate_default = excluded.reward_rate_default,
  reward_rate_categories = excluded.reward_rate_categories,
  welcome_benefits = excluded.welcome_benefits,
  milestone_benefits = excluded.milestone_benefits,
  lounge_access = excluded.lounge_access,
