  movie_benefits = excluded.movie_benefits,
  dining_benefits = excluded.dining_benefits,
  travel_insurance_cover = excluded.travel_insurance_cover,
  purchase_protection_cover = excluded.purchase_protection_cover,
  golf_access = excluded.golf_access,
  concierge_service = excluded.concierge_service,
  forex_markup = excluded.forex_markup,
  emi_conversion_available = excluded.emi_conversion_available,
  description = excluded.description,
  pros = excluded.pros,
  cons = excluded.cons,
  best_for = excluded.best_for,
  apply_url = excluded.apply_url,
